"""Run chart.py without saving, then report text boxes in the third panel that touch data lines or each other."""
import sys, numpy as np
src = open(sys.argv[1]).read().replace("fig.savefig(out, dpi=300)", "pass")
ns = {'__file__': sys.argv[1], '__name__': 'chk'}
exec(compile(src, sys.argv[1], 'exec'), ns)
fig, ax3 = ns['fig'], ns['ax3']
fig.set_dpi(300)
r = fig.canvas.get_renderer()
fig.draw(r)
pt = 300 / 72
boxes = []
for tx in ax3.texts:
    if not tx.get_text().strip():
        continue
    bb = tx.get_window_extent(r)
    boxes.append((tx.get_text().replace('\n', ' | '), bb))
# data lines: the step lines (Line2D with lw >= 2)
lines = [l for l in ax3.get_lines() if l.get_linewidth() >= 1.9 and len(l.get_xdata()) > 2]
def seg_hits(bb, path_xy, margin):
    x0, y0, x1, y1 = bb.x0 - margin, bb.y0 - margin, bb.x1 + margin, bb.y1 + margin
    P = path_xy
    for (ax_, ay), (bx, by) in zip(P[:-1], P[1:]):
        # step segments are axis-aligned after drawstyle; test the bounding box of the segment
        sx0, sx1 = min(ax_, bx), max(ax_, bx); sy0, sy1 = min(ay, by), max(ay, by)
        if sx1 >= x0 and sx0 <= x1 and sy1 >= y0 and sy0 <= y1:
            return (ax_, ay, bx, by)
    return None
for name, bb in boxes:
    for l in lines:
        # the drawn path: step 'post' expands
        x = l.get_xdata(); y = l.get_ydata()
        xy = l.get_transform().transform(np.column_stack([ns['md'].date2num(x), y]))
        st = []
        for i in range(len(xy) - 1):
            st.append(xy[i]); st.append((xy[i + 1][0], xy[i][1]))
        st.append(xy[-1])
        h = seg_hits(bb, st, margin=2 * pt)   # 2 pt clearance (the line is 2 pt wide)
        if h:
            print('TOUCH line', l.get_color(), ':', name)
for i in range(len(boxes)):
    for j in range(i + 1, len(boxes)):
        if boxes[i][1].overlaps(boxes[j][1]):
            print('TEXT OVERLAP:', boxes[i][0], '<>', boxes[j][0])
# leaders vs text boxes
for tx in ax3.texts:
    ap = getattr(tx, 'arrow_patch', None)
    if ap is None:
        continue
    path = ap.get_path().transformed(ap.get_transform()) if False else ap.get_path()
    verts = path.vertices
    for name, bb in boxes:
        if name == tx.get_text().replace('\n', ' | '):
            continue
        for v in np.linspace(verts[0], verts[-1], 400):
            if bb.contains(*v):
                print('LEADER of', tx.get_text().replace('\n', ' | '), 'crosses', name); break
for name, bb in boxes:
    print('%-50s x %.0f..%.0f y %.0f..%.0f' % (name[:50], bb.x0, bb.x1, bb.y0, bb.y1))
